/* ════════════════════════════════════════════════════════════════════════════
   E7 CANONICAL PROTOTYPE — Warmer Quiet Control Surface
   Tokens are traced verbatim to the latest prototype.html :root (warm hue 40/38),
   preserving the DESIGN.md identity: One Blue, Single-Border, Soft-Elevation,
   Tinted-Status, Structural-Navy, Orange-Sprinkle, Tabular-Numbers.
   ════════════════════════════════════════════════════════════════════════════ */
:root {
  /* Surfaces (warm) */
  --e7-bg:            hsl(40 30% 99%);
  --e7-surface:       hsl(40 30% 99%);          /* cards */
  --e7-surface-2:     hsl(38 22% 97%);          /* subtle panels */
  --e7-surface-3:     hsl(38 20% 95%);          /* hover fills */
  --e7-surface-4:     hsl(38 18% 92%);          /* pressed fills */
  --e7-surface-sunken:hsl(38 25% 96.5%);        /* main scroll area */

  /* Text (warm near-black) */
  --e7-text:          hsl(30 8% 12%);
  --e7-text-2:        hsl(30 6% 35%);
  --e7-text-3:        hsl(30 5% 50%);
  --e7-text-light:    hsl(30 5% 64%);
  --e7-text-inverted: hsl(0 0% 100%);

  /* Lines — Single-Border Rule */
  --e7-border:        hsl(38 18% 90%);
  --e7-border-strong: hsl(38 18% 82%);
  --e7-border-soft:   hsl(38 18% 90% / 0.7);

  /* Brand + action */
  --e7-brand:         hsl(210 40% 24%);         /* structural navy — never an action */
  --e7-brand-2:       hsl(210 36% 30%);
  --e7-brand-text:    hsl(210 40% 24%);
  --e7-brand-orange:  hsl(18 80% 48%);          /* ≤2 sprinkles/screen */
  --e7-action:        hsl(225 75% 55%);         /* The One Blue */
  --e7-action-hover:  hsl(225 75% 50%);
  --e7-action-active: hsl(225 75% 45%);
  --e7-action-subtle: hsl(225 75% 55% / 0.10);
  --e7-action-tint:   hsl(225 75% 55% / 0.14);
  --e7-action-text:   hsl(0 0% 100%);

  /* Status semantics (data state only) */
  --e7-done:          hsl(142 64% 38%);
  --e7-done-tint:     hsl(142 64% 38% / 0.14);
  --e7-done-text:     hsl(142 64% 28%);
  --e7-blocked:       hsl(0 72% 45%);
  --e7-blocked-tint:  hsl(0 72% 45% / 0.12);
  --e7-blocked-text:  hsl(0 72% 38%);
  --e7-warning:       hsl(38 92% 50%);
  --e7-warning-tint:  hsl(38 92% 50% / 0.18);
  --e7-warning-text:  hsl(28 80% 34%);
  --e7-violet:        hsl(262 60% 55%);         /* KPI/timeline only */
  --e7-violet-tint:   hsl(262 60% 55% / 0.12);
  --e7-violet-text:   hsl(262 60% 42%);

  /* Geometry */
  --e7-radius:            12px;          /* cards / containers / overlays */
  --e7-radius-control:    8px;           /* controls */
  --e7-radius-sm:         6px;
  --e7-radius-pill:       999px;
  --e7-rail-w:            232px;
  --e7-header-h:          56px;
  --e7-tabbar-h:          60px;
  --e7-panel-w:           460px;
  --e7-content-max:       1180px;

  --e7-control-h:         32px;
  --e7-control-h-lg:      40px;
  --e7-tap-h:             44px;
  --e7-row-h:             52px;

  /* Soft-Elevation shadows — navy-tinted, low-alpha (No-Pure-Black) */
  --e7-shadow-rest:    0 1px 2px hsl(210 40% 24% / 0.05), 0 1px 3px hsl(210 40% 24% / 0.04);
  --e7-shadow-lift:    0 2px 8px hsl(210 40% 24% / 0.07), 0 1px 2px hsl(210 40% 24% / 0.05);
  --e7-shadow-pop:     0 4px 16px hsl(210 40% 24% / 0.10), 0 1px 3px hsl(210 40% 24% / 0.06);
  --e7-shadow-overlay: 0 10px 30px hsl(210 40% 24% / 0.16), 0 2px 6px hsl(210 40% 24% / 0.08);

  /* Gradients — navy whispers only (never purple) */
  --e7-sheen-action:   linear-gradient(180deg, hsl(225 75% 58%) 0%, hsl(225 75% 52%) 100%);
  --e7-wash-surface:   linear-gradient(180deg, hsl(210 40% 24% / 0.035) 0%, transparent 220px);

  /* Type — Plus Jakarta (display) + DM Sans (body) + Inter (tabular) + SF Mono (IDs) */
  --e7-font-display:  "Plus Jakarta Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --e7-font-body:     "DM Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --e7-font-tabular:  "Inter", system-ui, -apple-system, sans-serif;
  --e7-font-mono:     "SF Mono", ui-monospace, "JetBrains Mono", Menlo, monospace;
  --e7-fs-page: 24px; --e7-fs-h: 20px; --e7-fs-sub: 18px;
  --e7-fs-body: 14px; --e7-fs-label: 12px; --e7-fs-overline: 11px; --e7-fs-mono: 12.5px;

  /* Spacing */
  --e7-s-xs:4px; --e7-s-sm:8px; --e7-s-md:12px; --e7-s-base:16px;
  --e7-s-lg:20px; --e7-s-xl:24px; --e7-s-2xl:32px; --e7-s-3xl:48px;

  color-scheme: light;
}

/* ── Reset ────────────────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; }
* { margin: 0; }
html { -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--e7-font-body);
  font-size: var(--e7-fs-body);
  line-height: 1.45;
  color: var(--e7-text);
  background: var(--e7-surface-sunken);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
h1,h2,h3,h4,h5 { font-family: var(--e7-font-display); font-weight: 600; line-height: 1.2; letter-spacing: -0.01em; color: var(--e7-text); }
h1 { font-size: var(--e7-fs-page); }
h2 { font-size: var(--e7-fs-h); line-height: 1.25; }
h3 { font-size: var(--e7-fs-sub); }
a { color: var(--e7-action); text-decoration: none; }
a:hover { text-decoration: underline; }
button { font: inherit; color: inherit; background: none; border: none; cursor: pointer; }
input, select, textarea { font: inherit; color: inherit; }
img, svg { display: block; max-width: 100%; }
:focus-visible { outline: 2px solid var(--e7-action); outline-offset: 2px; border-radius: var(--e7-radius-control); }
.sr-only, .sr-only-focusable:not(:focus) {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

/* ── Type utilities ───────────────────────────────────────────────────────── */
.tabular { font-family: var(--e7-font-tabular); font-feature-settings: "tnum" 1; font-variant-numeric: tabular-nums; }
.mono    { font-family: var(--e7-font-mono); font-size: var(--e7-fs-mono); letter-spacing: -0.01em; }
.overline { font-family: var(--e7-font-body); font-weight: 600; font-size: var(--e7-fs-overline); letter-spacing: 0.06em; text-transform: uppercase; color: var(--e7-text-3); }
.label { font-weight: 600; font-size: var(--e7-fs-label); color: var(--e7-text-2); }
.muted { color: var(--e7-text-2); }
.muted-2 { color: var(--e7-text-3); }
.muted-3 { color: var(--e7-text-light); }
.ico { width: 17px; height: 17px; flex: none; }

/* ════════════════════════════════════════════════════════════════════════════
   APP SHELL — desktop: rail | main under a top bar; panel overlays right
   ════════════════════════════════════════════════════════════════════════════ */
.e7-app {
  display: grid;
  grid-template-columns: var(--e7-rail-w) 1fr;
  grid-template-rows: var(--e7-header-h) 1fr;
  grid-template-areas: "rail header" "rail main";
  height: 100vh;
  height: 100dvh;
  overflow: hidden;
  background: var(--e7-bg);
}

/* ── Top bar ──────────────────────────────────────────────────────────────── */
.e7-topbar {
  grid-area: header;
  display: flex;
  align-items: center;
  gap: var(--e7-s-md);
  height: var(--e7-header-h);
  padding: 0 var(--e7-s-lg);
  background: var(--e7-bg);
  border-bottom: 1px solid var(--e7-border);
}
.e7-brand { display: inline-flex; align-items: center; gap: 9px; font-family: var(--e7-font-display); font-weight: 700; color: var(--e7-brand); font-size: 15px; letter-spacing: -0.01em; }
.e7-brand:hover { text-decoration: none; }
.e7-brand-square { width: 26px; height: 26px; border-radius: 7px; background: var(--e7-brand); display: inline-flex; align-items: center; justify-content: center; }
.e7-brand-dot { width: 7px; height: 7px; border-radius: var(--e7-radius-pill); background: var(--e7-brand-orange); }
.e7-brand-mos { color: var(--e7-text-3); font-weight: 500; margin-left: 3px; }
.e7-context-label { font-size: 13px; color: var(--e7-text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.e7-context-label b { color: var(--e7-text); font-weight: 600; }
.e7-topbar-spacer { flex: 1; }
.e7-cmdk {
  display: inline-flex; align-items: center; gap: var(--e7-s-sm);
  height: var(--e7-control-h); padding: 0 10px; background: var(--e7-surface);
  border: 1px solid var(--e7-border); border-radius: var(--e7-radius-control); color: var(--e7-text-3);
}
.e7-cmdk:hover { border-color: var(--e7-text-light); }
.e7-cmdk .ico { width: 15px; height: 15px; }
.e7-cmdk-text { font-size: 13px; }
.e7-kbd { font-family: var(--e7-font-mono); font-size: 11px; padding: 1px 5px; border: 1px solid var(--e7-border); border-radius: 5px; color: var(--e7-text-3); background: var(--e7-surface-2); }
.e7-iconbtn {
  position: relative; display: inline-flex; align-items: center; justify-content: center;
  width: var(--e7-control-h); height: var(--e7-control-h); border-radius: var(--e7-radius-control);
  color: var(--e7-text-3); border: 1px solid transparent;
}
.e7-iconbtn:hover { background: var(--e7-surface-3); color: var(--e7-text); }
.e7-iconbtn[aria-expanded="true"] { background: var(--e7-surface-3); color: var(--e7-text); }
.e7-dot { position: absolute; top: 4px; right: 4px; min-width: 15px; height: 15px; padding: 0 4px; border-radius: var(--e7-radius-pill); background: var(--e7-blocked); color: var(--e7-text-inverted); font-size: 10px; font-weight: 700; display: inline-flex; align-items: center; justify-content: center; font-family: var(--e7-font-tabular); }
.e7-create {
  display: inline-flex; align-items: center; gap: 6px; height: var(--e7-control-h);
  padding: 0 12px; background: var(--e7-action); color: var(--e7-action-text);
  border-radius: var(--e7-radius-control); font-weight: 600; font-size: 13px;
  box-shadow: 0 1px 2px hsl(225 75% 55% / 0.25);
}
.e7-create:hover { background: var(--e7-action-hover); }
.e7-create .ico { width: 15px; height: 15px; }
.e7-persona {
  display: inline-flex; align-items: center; gap: 8px; height: 34px; padding: 3px 8px 3px 3px;
  border-radius: var(--e7-radius-pill); border: 1px solid transparent;
}
.e7-persona:hover { background: var(--e7-surface-3); }
.e7-avatar { width: 28px; height: 28px; border-radius: var(--e7-radius-pill); display: inline-flex; align-items: center; justify-content: center; font-weight: 700; font-size: 12px; color: var(--e7-text-inverted); background: linear-gradient(135deg, var(--e7-brand) 0%, var(--e7-action) 100%); flex: none; }
.e7-persona-text { display: flex; flex-direction: column; line-height: 1.15; text-align: left; }
.e7-persona-text > span:first-child { font-weight: 600; font-size: 13px; color: var(--e7-text); }
.e7-persona-role { font-size: 11px; color: var(--e7-text-3); }
.e7-ham, .e7-ham::before, .e7-ham::after { display: block; width: 16px; height: 2px; background: var(--e7-text); border-radius: 2px; transition: transform .15s; }
.e7-ham { position: relative; }
.e7-ham::before, .e7-ham::after { content: ""; position: absolute; left: 0; }
.e7-ham::before { top: -5px; } .e7-ham::after { top: 5px; }

/* ── Rail ─────────────────────────────────────────────────────────────────── */
.e7-rail {
  grid-area: rail; background: var(--e7-surface); border-right: 1px solid var(--e7-border);
  display: flex; flex-direction: column; gap: var(--e7-s-lg); padding: var(--e7-s-lg) var(--e7-s-md); overflow-y: auto;
}
.e7-rail-group { display: flex; flex-direction: column; gap: 2px; }
.e7-rail-group > .overline { padding: 0 10px; margin-bottom: 2px; }
.e7-rail-modules { display: flex; flex-direction: column; gap: var(--e7-s-lg); }
.e7-rail-utility { margin-top: auto; border-top: 1px solid var(--e7-border); padding-top: var(--e7-s-md); }
.e7-nav-item {
  display: flex; align-items: center; gap: 10px; height: 36px; padding: 0 10px;
  border-radius: var(--e7-radius-control); color: var(--e7-text); font-size: 13.5px; font-weight: 500; text-decoration: none;
}
.e7-nav-item:hover { background: var(--e7-surface-3); text-decoration: none; }
.e7-nav-item.active { background: var(--e7-action-subtle); color: var(--e7-action-active); font-weight: 600; }
.e7-nav-item .ico { width: 17px; height: 17px; color: var(--e7-text-3); }
.e7-nav-item.active .ico { color: var(--e7-action); }
.e7-nav-item .e7-count { margin-left: auto; font-size: 11px; font-weight: 600; color: var(--e7-text-3); background: var(--e7-surface-3); padding: 0 7px; height: 18px; display: inline-flex; align-items: center; border-radius: var(--e7-radius-pill); }
.e7-nav-item.active .e7-count { background: var(--e7-action-tint); color: var(--e7-action-active); }
.e7-bu-group { display: flex; flex-direction: column; gap: 2px; }
.e7-bu-label { padding: 0 10px; }

/* ── Main ─────────────────────────────────────────────────────────────────── */
.e7-main {
  grid-area: main; overflow-y: auto; background: var(--e7-surface-sunken);
  background-image: var(--e7-wash-surface); background-repeat: no-repeat;
  scroll-behavior: smooth;
}
.e7-main:focus { outline: none; }
.e7-page { max-width: var(--e7-content-max); margin: 0 auto; padding: var(--e7-s-xl) var(--e7-s-2xl); }
.e7-page-head { display: flex; align-items: flex-start; gap: var(--e7-s-md); margin-bottom: var(--e7-s-xl); flex-wrap: wrap; }
.e7-page-head h1 { font-size: var(--e7-fs-page); }
.e7-page-head .muted-2 { margin-top: 2px; font-size: 13px; }
.e7-page-head .e7-head-actions { margin-left: auto; display: flex; gap: var(--e7-s-sm); align-items: center; flex-wrap: wrap; }
.e7-attention-flag { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 600; color: var(--e7-warning-text); background: var(--e7-warning-tint); padding: 4px 10px; border-radius: var(--e7-radius-pill); }
.e7-attention-flag .dot { width: 7px; height: 7px; border-radius: var(--e7-radius-pill); background: var(--e7-warning); }

/* ════════════════════════════════════════════════════════════════════════════
   PRIMITIVES — buttons, fields, pills, cards, tables, inline cell
   ════════════════════════════════════════════════════════════════════════════ */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: var(--e7-control-h); padding: 0 12px; border-radius: var(--e7-radius-control); font-size: 13px; font-weight: 600; border: 1px solid transparent; }
.btn:disabled { opacity: .5; cursor: not-allowed; pointer-events: none; }
.btn-primary { background: var(--e7-action); color: var(--e7-action-text); box-shadow: 0 1px 2px hsl(225 75% 55% / 0.25); }
.btn-primary:hover { background: var(--e7-action-hover); }
.btn-outline { background: var(--e7-surface); border-color: var(--e7-border); color: var(--e7-text); }
.btn-outline:hover { background: var(--e7-surface-3); }
.btn-ghost { color: var(--e7-text); }
.btn-ghost:hover { background: var(--e7-surface-3); }
.btn-destructive { background: var(--e7-blocked); color: var(--e7-text-inverted); }
.btn-sm { height: 28px; font-size: 12px; padding: 0 10px; }
.btn-ico { width: var(--e7-control-h); padding: 0; }
.btn .ico { width: 15px; height: 15px; }

.field {
  display: inline-flex; align-items: center; height: var(--e7-control-h); padding: 0 10px;
  background: var(--e7-surface); border: 1px solid var(--e7-border); border-radius: var(--e7-radius-control); width: 100%;
}
.field:focus-within { border-color: var(--e7-action); }
.field input, .field select, .field textarea { border: none; background: transparent; outline: none; width: 100%; }
.field textarea { min-height: 64px; padding: 6px 0; resize: vertical; line-height: 1.5; }
.field.invalid { border-color: var(--e7-blocked); }
.field-error { color: var(--e7-blocked-text); font-size: 12px; margin-top: 4px; }
.field-label { display: block; font-weight: 600; font-size: 12px; color: var(--e7-text-2); margin-bottom: 5px; }

/* Pills / badges — Tinted-Status (dot + ~14% tint + darkened text) */
.pill { display: inline-flex; align-items: center; gap: 6px; height: 22px; padding: 0 9px; border-radius: var(--e7-radius-pill); font-size: 12px; font-weight: 600; background: var(--e7-surface-3); color: var(--e7-text-2); white-space: nowrap; }
.pill .dot { width: 7px; height: 7px; border-radius: var(--e7-radius-pill); background: var(--e7-text-3); flex: none; }
.pill.open, .pill.progress { background: var(--e7-action-subtle); color: var(--e7-action-active); } .pill.open .dot, .pill.progress .dot { background: var(--e7-action); }
.pill.done { background: var(--e7-done-tint); color: var(--e7-done-text); } .pill.done .dot { background: var(--e7-done); }
.pill.blocked, .pill.lost { background: var(--e7-blocked-tint); color: var(--e7-blocked-text); } .pill.blocked .dot, .pill.lost .dot { background: var(--e7-blocked); }
.pill.warn, .pill.overdue { background: var(--e7-warning-tint); color: var(--e7-warning-text); } .pill.warn .dot, .pill.overdue .dot { background: var(--e7-warning); }
.pill.violet { background: var(--e7-violet-tint); color: var(--e7-violet-text); } .pill.violet .dot { background: var(--e7-violet); }
.pill.neutral { background: var(--e7-surface-3); color: var(--e7-text-2); }
.chip { display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 8px; border: 1px solid var(--e7-border); border-radius: var(--e7-radius-control); background: var(--e7-surface); font-size: 12px; color: var(--e7-text-2); cursor: pointer; }
.chip:hover { background: var(--e7-surface-3); }
.chip.active { border-color: var(--e7-brand); background: hsl(210 40% 24% / 0.06); color: var(--e7-brand-text); font-weight: 600; }
.basis-chip { display: inline-flex; align-items: center; height: 20px; padding: 0 8px; border-radius: var(--e7-radius-pill); background: var(--e7-surface-3); color: var(--e7-text-3); font-size: 11px; font-weight: 600; }

/* Card */
.card { background: var(--e7-surface); border: 1px solid var(--e7-border); border-radius: var(--e7-radius); box-shadow: var(--e7-shadow-rest); }
.card-head { display: flex; align-items: center; gap: var(--e7-s-sm); padding: var(--e7-s-md) var(--e7-s-base); border-bottom: 1px solid var(--e7-border); }
.card-head h3 { font-size: 15px; }
.card-head .ico { color: var(--e7-text-3); }
.card-head .actions { margin-left: auto; display: flex; gap: var(--e7-s-sm); align-items: center; }
.card-body { padding: var(--e7-s-base); }
.card-foot { padding: var(--e7-s-md) var(--e7-s-base); border-top: 1px solid var(--e7-border); display: flex; align-items: center; gap: var(--e7-s-sm); }

/* KPI tile */
.kpi { display: flex; flex-direction: column; gap: 6px; padding: var(--e7-s-base); background: var(--e7-surface); border: 1px solid var(--e7-border); border-radius: var(--e7-radius); box-shadow: var(--e7-shadow-rest); }
.kpi-top { display: flex; align-items: center; gap: var(--e7-s-sm); }
.kpi-ico { width: 30px; height: 30px; border-radius: var(--e7-radius-control); display: inline-flex; align-items: center; justify-content: center; background: var(--e7-action-subtle); color: var(--e7-action); }
.kpi-ico.violet { background: var(--e7-violet-tint); color: var(--e7-violet-text); }
.kpi-label { font-size: 12.5px; color: var(--e7-text-3); flex: 1; }
.kpi-value { font-family: var(--e7-font-tabular); font-size: 23px; font-weight: 600; letter-spacing: -0.01em; }
