/* ════════════════════════════════════════════════════════════════════════════
   E7 CANONICAL PROTOTYPE — Warmer Quiet Control Surface
   Tokens are traced verbatim to the latest prototype.html :root (warm hue 40/38),
   preserving the DESIGN.md identity: One Blue, Single-Border, Soft-Elevation,
   Tinted-Status, Structural-Navy, Orange-Sprinkle, Tabular-Numbers.
   ════════════════════════════════════════════════════════════════════════════ */
:root {
  /* Surfaces (warm) */
  --e7-bg:            hsl(40 30% 99%);
  --e7-surface:       hsl(40 30% 99%);          /* cards */
  --e7-surface-2:     hsl(38 22% 97%);          /* subtle panels */
  --e7-surface-3:     hsl(38 20% 95%);          /* hover fills */
  --e7-surface-4:     hsl(38 18% 92%);          /* pressed fills */
  --e7-surface-sunken:hsl(38 25% 96.5%);        /* main scroll area */

  /* Text (warm near-black) */
  --e7-text:          hsl(30 8% 12%);
  --e7-text-2:        hsl(30 6% 35%);
  --e7-text-3:        hsl(30 5% 50%);
  --e7-text-light:    hsl(30 5% 64%);
  --e7-text-inverted: hsl(0 0% 100%);

  /* Lines — Single-Border Rule */
  --e7-border:        hsl(38 18% 90%);
  --e7-border-strong: hsl(38 18% 82%);
  --e7-border-soft:   hsl(38 18% 90% / 0.7);

  /* Brand + action */
  --e7-brand:         hsl(210 40% 24%);         /* structural navy — never an action */
  --e7-brand-2:       hsl(210 36% 30%);
  --e7-brand-text:    hsl(210 40% 24%);
  --e7-brand-orange:  hsl(18 80% 48%);          /* ≤2 sprinkles/screen */
  --e7-action:        hsl(225 75% 55%);         /* The One Blue */
  --e7-action-hover:  hsl(225 75% 50%);
  --e7-action-active: hsl(225 75% 45%);
  --e7-action-subtle: hsl(225 75% 55% / 0.10);
  --e7-action-tint:   hsl(225 75% 55% / 0.14);
  --e7-action-text:   hsl(0 0% 100%);

  /* Status semantics (data state only) */
  --e7-done:          hsl(142 64% 38%);
  --e7-done-tint:     hsl(142 64% 38% / 0.14);
  --e7-done-text:     hsl(142 64% 28%);
  --e7-blocked:       hsl(0 72% 45%);
  --e7-blocked-tint:  hsl(0 72% 45% / 0.12);
  --e7-blocked-text:  hsl(0 72% 38%);
  --e7-warning:       hsl(38 92% 50%);
  --e7-warning-tint:  hsl(38 92% 50% / 0.18);
  --e7-warning-text:  hsl(28 80% 34%);
  --e7-violet:        hsl(262 60% 55%);         /* KPI/timeline only */
  --e7-violet-tint:   hsl(262 60% 55% / 0.12);
  --e7-violet-text:   hsl(262 60% 42%);

  /* Geometry */
  --e7-radius:            12px;          /* cards / containers / overlays */
  --e7-radius-control:    8px;           /* controls */
  --e7-radius-sm:         6px;
  --e7-radius-pill:       999px;
  --e7-rail-w:            232px;
  --e7-header-h:          56px;
  --e7-tabbar-h:          60px;
  --e7-panel-w:           460px;
  --e7-content-max:       1180px;

  --e7-control-h:         32px;
  --e7-control-h-lg:      40px;
  --e7-tap-h:             44px;
  --e7-row-h:             52px;

  /* Soft-Elevation shadows — navy-tinted, low-alpha (No-Pure-Black) */
  --e7-shadow-rest:    0 1px 2px hsl(210 40% 24% / 0.05), 0 1px 3px hsl(210 40% 24% / 0.04);
  --e7-shadow-lift:    0 2px 8px hsl(210 40% 24% / 0.07), 0 1px 2px hsl(210 40% 24% / 0.05);
  --e7-shadow-pop:     0 4px 16px hsl(210 40% 24% / 0.10), 0 1px 3px hsl(210 40% 24% / 0.06);
  --e7-shadow-overlay: 0 10px 30px hsl(210 40% 24% / 0.16), 0 2px 6px hsl(210 40% 24% / 0.08);

  /* Gradients — navy whispers only (never purple) */
  --e7-sheen-action:   linear-gradient(180deg, hsl(225 75% 58%) 0%, hsl(225 75% 52%) 100%);
  --e7-wash-surface:   linear-gradient(180deg, hsl(210 40% 24% / 0.035) 0%, transparent 220px);

  /* Type — Plus Jakarta (display) + DM Sans (body) + Inter (tabular) + SF Mono (IDs) */
  --e7-font-display:  "Plus Jakarta Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --e7-font-body:     "DM Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --e7-font-tabular:  "Inter", system-ui, -apple-system, sans-serif;
  --e7-font-mono:     "SF Mono", ui-monospace, "JetBrains Mono", Menlo, monospace;
  --e7-fs-page: 24px; --e7-fs-h: 20px; --e7-fs-sub: 18px;
  --e7-fs-body: 14px; --e7-fs-label: 12px; --e7-fs-overline: 11px; --e7-fs-mono: 12.5px;

  /* Spacing */
  --e7-s-xs:4px; --e7-s-sm:8px; --e7-s-md:12px; --e7-s-base:16px;
  --e7-s-lg:20px; --e7-s-xl:24px; --e7-s-2xl:32px; --e7-s-3xl:48px;

  color-scheme: light;
}

/* ── Reset ────────────────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; }
* { margin: 0; }
html { -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--e7-font-body);
  font-size: var(--e7-fs-body);
  line-height: 1.45;
  color: var(--e7-text);
  background: var(--e7-surface-sunken);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
h1,h2,h3,h4,h5 { font-family: var(--e7-font-display); font-weight: 600; line-height: 1.2; letter-spacing: -0.01em; color: var(--e7-text); }
h1 { font-size: var(--e7-fs-page); }
h2 { font-size: var(--e7-fs-h); line-height: 1.25; }
h3 { font-size: var(--e7-fs-sub); }
a { color: var(--e7-action); text-decoration: none; }
a:hover { text-decoration: underline; }
button { font: inherit; color: inherit; background: none; border: none; cursor: pointer; }
input, select, textarea { font: inherit; color: inherit; }
img, svg { display: block; max-width: 100%; }
:focus-visible { outline: 2px solid var(--e7-action); outline-offset: 2px; border-radius: var(--e7-radius-control); }
.sr-only, .sr-only-focusable:not(:focus) {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

/* ── Type utilities ───────────────────────────────────────────────────────── */
.tabular { font-family: var(--e7-font-tabular); font-feature-settings: "tnum" 1; font-variant-numeric: tabular-nums; }
.mono    { font-family: var(--e7-font-mono); font-size: var(--e7-fs-mono); letter-spacing: -0.01em; }
.overline { font-family: var(--e7-font-body); font-weight: 600; font-size: var(--e7-fs-overline); letter-spacing: 0.06em; text-transform: uppercase; color: var(--e7-text-3); }
.label { font-weight: 600; font-size: var(--e7-fs-label); color: var(--e7-text-2); }
.muted { color: var(--e7-text-2); }
.muted-2 { color: var(--e7-text-3); }
.muted-3 { color: var(--e7-text-light); }
.ico { width: 17px; height: 17px; flex: none; }

/* ════════════════════════════════════════════════════════════════════════════
   APP SHELL — desktop: rail | main under a top bar; panel overlays right
   ════════════════════════════════════════════════════════════════════════════ */
.e7-app {
  display: grid;
  grid-template-columns: var(--e7-rail-w) 1fr;
  grid-template-rows: var(--e7-header-h) 1fr;
  grid-template-areas: "rail header" "rail main";
  height: 100vh;
  height: 100dvh;
  overflow: hidden;
  background: var(--e7-bg);
}

/* ── Top bar ──────────────────────────────────────────────────────────────── */
.e7-topbar {
  grid-area: header;
  display: flex;
  align-items: center;
  gap: var(--e7-s-md);
  height: var(--e7-header-h);
  padding: 0 var(--e7-s-lg);
  background: var(--e7-bg);
  border-bottom: 1px solid var(--e7-border);
}
.e7-brand { display: inline-flex; align-items: center; gap: 9px; font-family: var(--e7-font-display); font-weight: 700; color: var(--e7-brand); font-size: 15px; letter-spacing: -0.01em; }
.e7-brand:hover { text-decoration: none; }
.e7-brand-square { width: 26px; height: 26px; border-radius: 7px; background: var(--e7-brand); display: inline-flex; align-items: center; justify-content: center; }
.e7-brand-dot { width: 7px; height: 7px; border-radius: var(--e7-radius-pill); background: var(--e7-brand-orange); }
.e7-brand-mos { color: var(--e7-text-3); font-weight: 500; margin-left: 3px; }
.e7-context-label { font-size: 13px; color: var(--e7-text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.e7-context-label b { color: var(--e7-text); font-weight: 600; }
.e7-topbar-spacer { flex: 1; }
.e7-cmdk {
  display: inline-flex; align-items: center; gap: var(--e7-s-sm);
  height: var(--e7-control-h); padding: 0 10px; background: var(--e7-surface);
  border: 1px solid var(--e7-border); border-radius: var(--e7-radius-control); color: var(--e7-text-3);
}
.e7-cmdk:hover { border-color: var(--e7-text-light); }
.e7-cmdk .ico { width: 15px; height: 15px; }
.e7-cmdk-text { font-size: 13px; }
.e7-kbd { font-family: var(--e7-font-mono); font-size: 11px; padding: 1px 5px; border: 1px solid var(--e7-border); border-radius: 5px; color: var(--e7-text-3); background: var(--e7-surface-2); }
.e7-iconbtn {
  position: relative; display: inline-flex; align-items: center; justify-content: center;
  width: var(--e7-control-h); height: var(--e7-control-h); border-radius: var(--e7-radius-control);
  color: var(--e7-text-3); border: 1px solid transparent;
}
.e7-iconbtn:hover { background: var(--e7-surface-3); color: var(--e7-text); }

