@import "tailwindcss";

/* ════════════════════════════════════════════════════════════════════════════
   Gordi MOS — global stylesheet entry
   ════════════════════════════════════════════════════════════════════════════
   Token source of truth: the mos-design-kit (ADR-0009, 2026-06-19). The kit's
   --ds-* tokens are authored in color(display-p3 …) and degrade gracefully to
   sRGB. Light is default (:root); dark is opt-in (.dark on a container).
   Fonts load via @fontsource packages in main.tsx (Plus Jakarta + DM Sans,
   OD-P3-9) — NOT via CSS @import, so we do not import the kit's fonts.css here.
   ════════════════════════════════════════════════════════════════════════════ */

/* Raw token scales — light = :root default, dark = .dark scope. App-owned copies
   of the clean-room kit values (docs/reference/mos-design-kit/ is the reference
   of record; the app does not reach into docs/ at runtime). */
@import "./styles/tokens/theme-light.css";
@import "./styles/tokens/theme-dark.css";
@import "./styles/tokens/aliases.css";

/* ── Gordi brand tokens (OD-P3-7 / ADR-0008 D4) — additions on top of the kit.
   The kit has no brand tokens; navy/orange are ratified Gordi identity.
   Converted from their ratified HSL values to color(display-p3 …) (ADR-0009 D2).
   Present in both light and dark; navy-text lightened for AA on dark surfaces. */
:root,
.light {
  --brand-navy:      color(display-p3 0.0313 0.0311 0.0893); /* hsl(218 46% 22%)  — structural weight */
  --brand-navy-text: color(display-p3 0.0435 0.0436 0.1192); /* hsl(218 42% 26%)  — AA text on light */
  --brand-orange:    color(display-p3 0.9 0.45 0.2);          /* vivid orange — brand sprinkle / active-tab accent (was a bad dark-brown p3 conversion) */
  /* Status-pill darkened-AA text tokens (DESIGN.md §5 / ADR-0008) — P3 form */
  --status-open-text:   color(display-p3 0.1001 0.0765 0.4201); /* hsl(221 75% 38%) */
