/* ── Tasks table + split-view shell styles (PR-B) ──────────────────────────────
   Extracted from TasksPage's inline <style> so both the standalone full-page
   host AND the split-view shell render identically. Every value resolves to a
   DESIGN.md token; the only literal px are layout dimensions (sizes/radii) and
   the documented drawer width clamp (OD-P3-2).
   ──────────────────────────────────────────────────────────────────────────── */

/* ── Page head ── */
/* IA-1: the page head is the shared shell/PageHead.tsx (title + meta beside it, full-bleed —
   no maxWidth cap). The bespoke .page-head-row / .tasks-page-title / .tasks-count-line
   classes were removed; only the head-owned controls below remain. */

/* ── Content header (mockup `.content-header`) ──────────────────────────────────
   The list/DB-view header chrome: a single clean row = entity icon + title +
   count pill + right-aligned inline action. Pixel oracle:
   docs/design-mockups/ui-revamp/mock-shell-and-table.html `.content-header`.
   Every value resolves to a DESIGN.md token (crosswalk of the mockup's --ds-*). */
.content-header {
  display: flex; align-items: center; gap: 10px;
  min-height: 48px; margin-bottom: 16px;
  padding-bottom: 14px; border-bottom: 1px solid var(--border);
}
.content-header .ch-icon { color: var(--muted-foreground); display: inline-flex; flex: none; }
.content-header .ch-title {
  font-weight: 600; font-size: 24px; letter-spacing: -0.01em; color: var(--foreground);
  margin: 0; line-height: 1.2;
}
/* Count pill (mockup `.ch-count`) — small muted pill on the tertiary surface. */
.content-header .ch-count {
  font-size: 11px; font-weight: 600; color: var(--muted-foreground);
  background: var(--secondary); padding: 2px 9px; border-radius: 999px;
  flex: none; line-height: 1.4;
}
/* Overdue/blocked subtotals + clearable filter chips ride just after the pill. */
.content-header .ch-meta { display: inline-flex; align-items: center; gap: 10px; flex-wrap: wrap; }
/* Right-aligned inline action (mockup `.ch-action`) — pushed to the far edge. */
.content-header .ch-action { margin-left: auto; flex: none; }
/* Off-track subtotals (blocked / overdue) ride beside the count pill. */
.ch-submeta { color: var(--muted-foreground); font-size: 15px; }

/* ── Split-view grid (the push/squash master-detail, ADR-0007) ── */
.split {
  display: grid;
  grid-template-columns: minmax(0, 1fr) clamp(360px, 33vw, 480px); /* OD-P3-2 drawer width; minmax(0,1fr) not bare 1fr so wide card/table content can't stretch the track past the viewport (min-width:auto blowout) */
  align-items: start; gap: 12px;
  /* CONV (owner-directed 2026-06-17): the data workspace runs FULL-BLEED — no max-width cap.
     It fills PageFrame's 24px gutters, which equal the topbar's px-6 gutter, so the table's
     right edge aligns with the account chip (no detached 1/3-width content on wide monitors).
     Only the Task column (1fr) absorbs the extra width; the other columns are fixed-px, so
     nothing balloons. A generous safety cap guards absurd ultra-wide Task columns only. */
  max-width: 1760px;
}
.split.nodrawer { grid-template-columns: minmax(0, 1fr); }
/* Expanded focus mode: table hidden, drawer fills the row. */
.split.expanded { grid-template-columns: 1fr; }
.split.expanded .assembly { display: none; }

/* ── Card assembly (OD-P3-10/11) ── */
.assembly {
  background: var(--card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); /* 12px — card surface, OD-P3-10 */
  box-shadow: var(--shadow-rest); /* OD-P3-11 resting lift */
  overflow: hidden; min-width: 0;
}

/* ── Drawer pane (the aside hosting TaskSurface, OD-P3-10/11) ──
   The generic .drawer / .drawer-modal-root / .drawer-scrim / .drawer-modal.drawer-sheet /
   .drawer-modal.drawer-fullscreen chrome now lives in styles/drawer.css (loaded globally
   in main.tsx) — the Signal composer/record hosts are mounted at the shell root, outside
   this route-scoped stylesheet, and need the same chrome. Only Task-specific extensions
   (the .dw-* selectors below) stay here. */
/* The modal drawer fills its sheet/fullscreen container (pinned head + scroll body + foot). */
.drawer-modal .dw-surface { flex: 1; min-height: 0; border: 0; border-radius: 0; }
/* Mobile (<768px): ≥44px touch targets + a horizontally-scrollable tab strip. */
.drawer-modal.drawer-fullscreen .dw-iconbtn { width: 44px; height: 44px; }
.drawer-modal.drawer-fullscreen .dw-tabs { overflow-x: auto; flex-wrap: nowrap; }
.drawer-modal.drawer-fullscreen .dw-tab { min-height: 44px; white-space: nowrap; }
.drawer-modal.drawer-fullscreen .btn-ghost-danger,
.drawer-modal.drawer-fullscreen .checklist-checkbox { min-height: 44px; }

/* ── Toolbar ── (mockup `.toolbar`: view-tabs · spacer · segment · chips · search) */
.toolbar {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 8px 12px;
  border-bottom: 1px solid var(--border);
}
.tb-spacer { flex: 1 1 0; min-width: 8px; }

/* F-A / OD-REDESIGN-61: member phones see work before configuration. The
   existing toolbar remains the one options surface; only its disclosure chrome
   is added for the least-technical mobile persona. */
.mobile-task-options {
  border-bottom: 1px solid var(--border);
  background: var(--card);
}
.mobile-task-options-trigger {
  display: flex; align-items: center; width: 100%; min-height: 44px;
  padding: 0 12px; border: 0; background: transparent; color: var(--foreground);
  font: inherit; font-size: 15px; font-weight: 600; text-align: left; cursor: pointer;
}
.mobile-task-options-trigger:hover { background: var(--secondary); }
.mobile-task-options-trigger:focus-visible { outline: 2px solid var(--ring); outline-offset: -2px; }
.mobile-task-options-summary { margin-left: 4px; color: var(--muted-foreground); font-weight: 500; }
.mobile-task-options-chevron {
  display: block; margin-left: auto; color: var(--muted-foreground);
  transition: transform 150ms ease;
}
.mobile-task-options-chevron--open { transform: rotate(180deg); }
.mobile-task-options-panel .toolbar { border-bottom: 0; }
@media (prefers-reduced-motion: reduce) {
  .mobile-task-options-chevron { transition: none; }
}

/* View-tabs inside the toolbar: the shared ViewTabs primitive defaults to the
   full-width sticky strip (the dashboard placement — view-tabs.css); here it sits
   INLINE as the first toolbar item, so the strip chrome (padding/border/sticky/
   background) is reset. The tab grammar (muted → brand-navy-text + the brand-orange
   underline) is shared and untouched. */
.toolbar .view-tabs {
  padding: 0;
  border-bottom: 0;
  position: static;
  background: transparent;
  z-index: auto;
}

/* Chip-style filter control (mockup `.chip`): bordered pill = label + current value
   + ▾; a transparent native <select> overlay preserves full filter capability + a11y. */
.chip {
  position: relative; display: inline-flex; align-items: center; gap: 6px;
  height: 32px; padding: 0 10px;
  border: 1px solid var(--input); border-radius: var(--radius-sm); /* 8px — control, OD-P3-10 */
  background: var(--background); font-size: 15px; color: var(--secondary-foreground); cursor: pointer;
}
.chip:hover { border-color: var(--border-strong); }
.chip:focus-within { outline: 2px solid var(--ring); outline-offset: 1px; }
.chip .ch-k { color: var(--muted-foreground); }
.chip .ch-v { color: var(--foreground); font-weight: 500; max-width: 120px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chip .chip-chev { color: var(--muted-foreground); pointer-events: none; flex: none; }
/* The native select sits invisibly over the chip — clicks open the native menu. */
.chip-select { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; cursor: pointer; font-size: 15px; border: 0; }

.seg { display: inline-flex; height: 32px; padding: 3px; background: var(--secondary); border-radius: var(--radius-sm); /* 8px — control, OD-P3-10 */ }
.seg-btn {
  border: 0; background: transparent; font: inherit; font-size: 15px; padding: 0 10px;
  border-radius: calc(var(--radius-sm) - 2px); /* inner control corner OD-P3-10 */
  color: var(--secondary-foreground); cursor: pointer; white-space: nowrap;
}
/* Active segment: crisp 1px ring + lift so it's clearly "the one that's on"
   against the grey track (no layout shift — ring drawn via box-shadow). */
.seg-btn-on {
  background: var(--background); font-weight: 600;
  box-shadow: 0 0 0 1px var(--border-strong), 0 1px 2px color-mix(in srgb, var(--ds-font-color-primary) 18%, transparent);
}
.search-mini {
  height: 32px; display: inline-flex; align-items: center; gap: 6px; padding: 0 10px;
  border: 1px solid var(--input); border-radius: var(--radius-sm); /* 8px — control, OD-P3-10 */
  color: var(--muted-foreground);
  font-size: 15px; min-width: 180px;
}
.search-input { border: none; outline: none; background: transparent; font: inherit; font-size: 15px; color: var(--foreground); width: 100%; }
.search-input::placeholder { color: var(--muted-foreground); }
.archived-toggle {
  display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 10px;
  border: 1px solid var(--input); background: var(--background);
  border-radius: var(--radius-sm); /* 8px — control, OD-P3-10 */
  font-size: 15px; cursor: pointer; color: var(--foreground);
}
/* Custom checkbox (DESIGN.md §5 checkbox spec) so 'Show archived' reads as a deliberate
   control, not a raw native checkbox — consistent with the other toolbar pills. */
.archived-checkbox {
  appearance: none; -webkit-appearance: none; width: 16px; height: 16px; cursor: pointer;
  border: 1.5px solid var(--input); border-radius: 4px; background: var(--background);
  display: inline-grid; place-content: center; flex: none; margin: 0;
}
.archived-checkbox:checked { background: var(--primary); border-color: var(--primary); }
.archived-checkbox:checked::after { content: "✓"; color: var(--primary-foreground); font-size: 11px; font-weight: 700; line-height: 1; }
.archived-checkbox:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }
.archived-label { font-size: 15px; }
.toolbar-overdue-controls { display: inline-flex; align-items: center; gap: 8px; }

/* ── M6: condensed (drawer-open) toolbar ──
   At the squashed column width the labelled controls + segmented control +
   search + archived toggle wrap. We KEEP the in-control text labels (the four
   filter controls must retain their identity — Group / Business unit / Status /
   Person — never collapsing to anonymous '▾' stubs), let the search flex, and
   tighten gaps. (Recognition failure > row count.) */
.assembly.condensed .toolbar { gap: 6px; padding: 8px 10px; }
/* Keep the in-chip labels in condensed mode so the four filter chips retain their
   identity (Group / Unit / Status / Person) — never collapse to anonymous '▾' stubs. */
.assembly.condensed .toolbar .chip { padding: 0 8px; }
.assembly.condensed .toolbar .seg-btn { padding: 0 8px; }
.assembly.condensed .toolbar .search-mini { min-width: 120px; flex: 1 1 120px; }
.assembly.condensed .toolbar .archived-toggle { padding: 0 8px; }

/* ── Table scroll container ──
   Non-virtual: a passthrough wrapper with overflow-x:auto so a 10-column fixed
   layout scrolls horizontally instead of starving the Task column (RI-3 fix).
   Virtual (AC-114, 50+ rows): a bounded scroll viewport so @tanstack/react-virtual
   can window the rows. The <thead> with aria-sort stays sticky atop the viewport. */
.tasks-scroll { min-width: 0; max-width: 100%; overflow-x: auto; }
.tasks-scroll-virtual { max-height: 70vh; overflow-y: auto; }
.tasks-scroll-virtual thead th { position: sticky; top: 0; z-index: 1; background: var(--card); }

/* ── Table ── */
/* Wave 2c (OD-REDESIGN-61..64, e7 priority columns): the desktop DB-view shows ONLY
   the decision columns — cb + Task + Status + PIC + Supervisor + Due + menu (7 cols).
   Project/Process, Objective, Team, Source, Activity moved to the record drawer
   (where the typed Task already shows them — OD-62). min-width:0 (was 1284px) so
   width:100% + table-layout:fixed always fit the content area — the decision-critical
   Due column can NEVER be clipped off-screen at 1280px. .tasks-scroll (overflow-x:auto)
   is the safety net only for absurdly narrow shells. */
.tasks-table { width: 100%; border-collapse: collapse; table-layout: fixed; min-width: 0; }
/* Priority col widths: cb + menu fixed 40px; Task absorbs the remainder (auto);
   the four decision cols get fixed px so their headers/labels never wrap or squash. */
.tasks-table th:nth-child(1), .tasks-table td:nth-child(1) { width: 40px; }   /* checkbox */
.tasks-table th:nth-child(2), .tasks-table td:nth-child(2) { width: auto; }   /* Task */
.tasks-table th:nth-child(3), .tasks-table td:nth-child(3) { width: 150px; }  /* Status */
.tasks-table th:nth-child(4), .tasks-table td:nth-child(4) { width: 184px; }  /* PIC / Ownership */
.tasks-table th:nth-child(5), .tasks-table td:nth-child(5) { width: 168px; }  /* Supervisor */
.tasks-table th:nth-child(6), .tasks-table td:nth-child(6) { width: 132px; }  /* Due */
.tasks-table th:nth-child(7), .tasks-table td:nth-child(7) { width: 40px; }   /* row menu */
/* Condensed (drawer-open split): %-based widths so the 7 priority cols flex to the
   narrow split; cb + menu stay fixed 40px. */
.assembly.condensed .tasks-table th:nth-child(1), .assembly.condensed .tasks-table td:nth-child(1) { width: 40px; }
.assembly.condensed .tasks-table th:nth-child(2), .assembly.condensed .tasks-table td:nth-child(2) { width: auto; }
.assembly.condensed .tasks-table th:nth-child(3), .assembly.condensed .tasks-table td:nth-child(3) { width: 18%; }  /* Status */
.assembly.condensed .tasks-table th:nth-child(4), .assembly.condensed .tasks-table td:nth-child(4) { width: 16%; }  /* PIC */
.assembly.condensed .tasks-table th:nth-child(5), .assembly.condensed .tasks-table td:nth-child(5) { width: 18%; }  /* Supervisor */
.assembly.condensed .tasks-table th:nth-child(6), .assembly.condensed .tasks-table td:nth-child(6) { width: 16%; }  /* Due */
.assembly.condensed .tasks-table th:nth-child(7), .assembly.condensed .tasks-table td:nth-child(7) { width: 40px; }
/* Checkbox / menu col alignment + header (PR-2 AC-T02/T07). */
.td-cb, .th-cb { text-align: left; white-space: nowrap; padding-left: 12px; }
.td-menu, .th-menu { text-align: right; white-space: nowrap; padding-right: 12px; }
/* Condensed PIC: drop the name, keep the avatar (AC-113 ladder step 2). */
.assembly.condensed .td-owner .own-name { display: none; }

/* OD-P4-10 overline, scoped to thead th ONLY (group headers + rail labels keep
   weight 600/500). Weight 400 + UPPERCASE + 0.06em tracking, color
   --muted-foreground (the --ds-font-color-tertiary crosswalk — clears dark-mode AA,
   ADR-0013 Decision 2). Mockup: mock-shell-and-table.html `.records thead th`. */
.th-cell {
  text-align: left; height: 32px; padding: 0 12px; line-height: 1.3;
  font-weight: 400; text-transform: uppercase; letter-spacing: 0.06em;
  /* Mockup overline is a literal 11px (the kit --ds-font-size-xs resolves ~13.6px, too large for this role). */
  font-size: 11px; color: var(--muted-foreground);
  border-bottom: 1px solid var(--border); white-space: nowrap;
}
.th-sortable { cursor: pointer; }
.th-sortable:hover { color: var(--foreground); }
.th-sorted { color: var(--foreground); }
/* Sort affordance MUST be inline-block: Tailwind preflight sets `svg { display:block }`,
   and a block-level SVG ignores the cell's text-align and drops to its own line at the left
   (detaching the arrow from its column label). inline-block + middle keeps it beside the label. */
.sort-aff { display: inline-block; vertical-align: middle; width: 10px; height: 10px; margin-left: 5px; color: var(--primary); }
.td-main, .td-cell {
  height: 50px; line-height: 1.4; padding: 0 12px; border-bottom: 1px solid color-mix(in srgb, var(--border-medium) 70%, transparent); vertical-align: middle; /* OD-P3-6: dense DB-view row (not the 54px default); line-height pins the box so a short single-line cell can't collapse the 50px below ~38px (capstone regression). */
}
/* Due/Activity: LEFT-aligned like every other column (uniform grid), but never wrap. */
.td-nowrap { white-space: nowrap; }
/* OD-P3-6 robust pin: also set the height on the ROW. `height` on a <td> is only a
   minimum and the live capstone review measured ~38.5px; pinning the <tr> (higher
   specificity context for the cells) holds the dense 50px regardless of cell content. */
.task-row { cursor: pointer; height: 50px; }
.task-row:last-child td { border-bottom: none; }
.task-row:hover td { background: color-mix(in srgb, var(--surface-secondary) 60%, transparent); }
.task-row.row-selected td { background: var(--secondary); } /* CONV: neutral-grey selected/open row — de-blued (owner pref + One-Blue Rule) */
/* AC-109 keyboard cursor: a plain primary 2px inset rule (no new --kbd-cursor token,
   design-plan §6.2). box-shadow inset keeps the row height stable (no layout shift). */
.task-row.kfocus td { box-shadow: inset 0 2px 0 var(--primary), inset 0 -2px 0 var(--primary); }
.task-row.kfocus td:first-child { box-shadow: inset 2px 2px 0 var(--primary), inset 0 -2px 0 var(--primary); }
.task-row.kfocus td:last-child { box-shadow: inset -2px 2px 0 var(--primary), inset 0 -2px 0 var(--primary); }
.task-row-link { display: block; text-decoration: none; color: inherit; border-radius: var(--radius-sm); }
/* PR-2 AC-T03 — kit name-chip: hover background (the open-the-record affordance). */
.task-row-link:hover { background: var(--secondary); }
.task-row-link:focus-visible { outline: 2px solid var(--ring); outline-offset: -2px; }

/* PR-2 AC-T02 — hover-revealed row checkbox + ⋯ menu (kit "quiet at rest" craft).
   visibility:hidden at rest; revealed on tr:hover / tr.row-selected / tr:focus-within
   (keyboard reachable via :focus-within, never hover-only — ADR-0013 §2.7). */
.row-checkbox {
  width: 16px; height: 16px; flex: none; padding: 0; cursor: pointer;
  border: 1.5px solid var(--input); border-radius: var(--radius-xs); background: transparent;
  display: inline-flex; align-items: center; justify-content: center;
  visibility: hidden; /* quiet at rest — revealed by the rules below */
}
.row-checkbox:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; visibility: visible; }
.row-checkbox-on { background: var(--primary); border-color: var(--primary); }
.row-checkbox-on::after {
  content: '✓'; color: var(--primary-foreground); font-size: 11px; font-weight: 700; line-height: 1;
}
tr:hover .row-checkbox,
tr.row-selected .row-checkbox,
tr:focus-within .row-checkbox { visibility: visible; }

/* PR-2 AC-T02 — hover-revealed ⋯ row menu (same reveal contract as the checkbox). */
.row-menu {
  width: 24px; height: 24px; flex: none; padding: 0; cursor: pointer;
  display: inline-flex; align-items: center; justify-content: center;
  border: 0; background: transparent; color: var(--muted-foreground);
  border-radius: var(--radius-xs); visibility: hidden;
}
.row-menu:hover { background: var(--accent); color: var(--foreground); }
.row-menu:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; visibility: visible; }
.row-menu-wrap { position: relative; display: inline-flex; }
.row-menu-pop {
  position: absolute; right: 0; top: calc(100% + 2px); z-index: 20; min-width: 120px;
  background: var(--popover); border: 1px solid var(--border); border-radius: var(--radius-sm);
  box-shadow: var(--shadow-rest); padding: 4px; display: flex; flex-direction: column;
}
.row-menu-item {
  padding: 6px 10px; border-radius: var(--radius-xs); color: var(--foreground);
  text-decoration: none; font-size: 15px; white-space: nowrap;
}
.row-menu-item:hover { background: var(--accent); }
tr:hover .row-menu,
tr.row-selected .row-menu,
tr:focus-within .row-menu { visibility: visible; }
.task-title-line { display: flex; align-items: center; gap: 6px; overflow: hidden; }
.task-name {
  font-weight: 600; font-size: 15.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  display: block; color: var(--foreground); min-width: 0;
}
.task-name-archived { font-weight: 500; color: var(--muted-foreground); }
.archived-tag {
  display: inline-flex; align-items: center; height: 18px; padding: 0 6px; border-radius: 4px;
  background: var(--secondary); color: var(--muted-foreground);
  font-size: 11px; font-weight: 500; white-space: nowrap; flex: none;
}
.task-bu { display: block; font-size: 12px; color: var(--muted-foreground); margin-top: 2px; }

/* ── Owner cell ── */
.owner { display: flex; align-items: center; gap: 8px; }
.ownav {
  width: 26px; height: 26px; border-radius: 999px;
  /* Mockup .av-sm avatar: blue12→blue9 gradient + inverted text. blue12 flips with the theme
     (dark navy in light / light blue in dark), so the inverted initials always clear WCAG-AA
     (~8:1 light, ~7:1 dark at the gradient centre). The prior solid --accent + dark
     --brand-navy-text was only ~3.67:1 — the illegible initials. Keep this pairing. */
  background: linear-gradient(135deg, var(--ds-color-blue12), var(--ds-color-blue9));
  color: var(--ds-font-color-inverted); display: grid; place-items: center; font-size: 10.5px; font-weight: 700; flex: none;
}
.own-name { font-size: 15px; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* Design fix wave item 4 (OD-65 mockup regression) — the generated-ownership "via <role name>"
   line stacks below the PIC name (never widens the compact owner cell). */
.owner-name-stack { display: flex; flex-direction: column; gap: 1px; min-width: 0; overflow: hidden; }
.owner-name-stack .own-name { line-height: 1.2; }
.owner-provenance {
  font-size: 11px; color: var(--muted-foreground); font-weight: 500;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.assembly.condensed .td-owner .owner-provenance { display: none; }
/* Business unit column (mockup '.bu') — muted, truncates */
.td-bu { font-size: 13px; color: var(--muted-foreground); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* ── Due-date coloring ── */
.due-overdue { color: var(--status-lost-text); font-weight: 600; font-size: 15px; }
.due-soon    { color: var(--warning-foreground); font-weight: 600; font-size: 15px; }
.due-calm    { color: var(--muted-foreground); font-weight: 500; font-size: 15px; }
.act { color: var(--muted-foreground); font-size: 12px; font-weight: 500; }

/* ── Loading skeleton ── */
.sk-cell { height: 50px; padding: 0 12px; border-bottom: 1px solid color-mix(in srgb, var(--border-medium) 70%, transparent); vertical-align: middle; }
.sk { background: var(--secondary); border-radius: 6px; height: 12px; display: inline-block; animation: sk-pulse 1.4s ease-in-out infinite; }
.sk.pill { height: 22px; width: 84px; border-radius: 999px; display: block; }
.sk.av { height: 26px; width: 26px; border-radius: 999px; display: block; }
@keyframes sk-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.55; } }
.skeleton-cards { padding: 8px 12px; }
.sk-card-row { display: flex; align-items: center; gap: 12px; padding: 0 0 12px 0; height: 50px; border-bottom: 1px solid color-mix(in srgb, var(--border-medium) 70%, transparent); }

/* ── Error / Empty (IXD-5, PR-2) ── */
/* The Tasks error + empty states use the shared <ErrorState> / <EmptyState>
   (ui/StateKit → CardHead.css .error-state / .empty-state), and the action buttons
   use .btn .btn-{variant} (ui/Button.css). The bespoke .error-banner / .error-text /
   .retry-btn / .empty-state / .empty-title / .empty-copy / .empty-actions / .btn-primary /
   .btn-outline rules were removed (no duplication of the shared kit). */

/* ── New task — lives in the toolbar as the right-aligned primary action (mockup
   '.btn-primary.grow'); the orphan '.table-top-bar' strip was removed (OD-P3-6 tidy). */
.toolbar-new-task { margin-left: auto; }

/* ── Mobile card list (OD-P3-10/11) ── */
.task-card {
  background: var(--card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); /* 12px — mobile reflow card, OD-P3-10 */
  box-shadow: var(--shadow-rest); /* OD-P3-11 resting lift */
  overflow: hidden;
}
.task-card-link { display: block; padding: 12px 16px; text-decoration: none; color: inherit; min-height: 44px; }
.task-card-link:focus-visible { outline: 2px solid var(--ring); outline-offset: -2px; }
.task-card-head { display: flex; align-items: flex-start; gap: 8px; flex-wrap: wrap; margin-bottom: 2px; }
