   header field grid with real separations, sectioned regions (mentions/category/edited/
   acknowledge/linked-work), each divided by a hairline. Reuses signal-card.css's attention
   pill + category-picker anchor (same classes, same visual language as the feed card) — the
   component imports both stylesheets rather than duplicating those rules here. */

.signal-record { padding: 16px; display: flex; flex-direction: column; gap: 14px; }
.signal-record--retracted { padding: 12px 16px; }

/* ── Header field grid — author/team/BU/site/occurred + the attention pill, each label a
   short span so the whole row reads as one scannable line but keeps real gaps (MINOR-7/8). ── */
.signal-record-head {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px 14px;
  padding-bottom: 12px; border-bottom: 1px solid var(--border);
}
.signal-record-author { font-weight: 600; color: var(--foreground); font-size: 13.5px; }
.signal-record-team,
.signal-record-bu,
.signal-record-site,
.signal-record-occurred { font-size: 12.5px; color: var(--muted-foreground); }
.signal-record-head .signal-attention { margin-left: auto; }

.signal-record-body { margin: 0; font-size: 14.5px; line-height: 1.6; color: var(--foreground); }

.signal-record-mentions {
  display: flex; flex-wrap: wrap; gap: 6px; margin: 0; padding: 0; list-style: none;
}
.signal-record-mentions li {
  display: inline-flex; align-items: center; height: 22px; padding: 0 8px;
  border-radius: var(--radius-pill); background: var(--accent-subtle); color: var(--text-accent);
  font-size: 12px; font-weight: 600;
}

.signal-record-vis { margin: 0; font-size: 12px; color: var(--muted-foreground); }

.signal-record-category { display: flex; }

.signal-record-edited { font-size: 12.5px; }
.signal-record-edited > button {
  background: none; border: none; padding: 0; font: inherit; color: var(--text-accent);
  cursor: pointer; text-decoration: underline;
}
.signal-record-revisions {
  margin: 8px 0 0; padding: 8px 10px; list-style: none;
  display: flex; flex-direction: column; gap: 6px;
  background: var(--secondary); border-radius: var(--radius-sm);
  font-size: 12px; color: var(--muted-foreground);
}
.signal-record-revisions li { display: flex; gap: 8px; flex-wrap: wrap; }

.signal-record-ack {
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
  padding-top: 12px; border-top: 1px solid var(--border);
}
.signal-ack-list { display: flex; gap: 6px; flex-wrap: wrap; margin: 0; padding: 0; list-style: none; }
.signal-ack-name {
  display: inline-flex; align-items: center; height: 22px; padding: 0 8px;
  border-radius: var(--radius-pill); background: var(--secondary); color: var(--muted-foreground);
  font-size: 12px;
}

/* "Linked work" section (MINOR-7/8 spacing) — a clear divider + heading before the actions. */
.signal-record-linked-work {
  display: flex; flex-direction: column; gap: 8px;
  padding-top: 12px; border-top: 1px solid var(--border);
}
.signal-record-linked-work h2 {
  margin: 0; font-size: 13px; font-weight: 600; color: var(--foreground);
}
.signal-record-linked-work p { margin: 0; font-size: 13px; color: var(--muted-foreground); }
.signal-record-linked-work-actions { display: flex; gap: 8px; flex-wrap: wrap; }

